import{_ as n,o as r,c as a,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const g=JSON.parse('{"title":"Zentrale Prüfungen und Klausuren bearbeiten","description":"","frontmatter":{},"headers":[],"relativePath":"zeugnisse/zp10.md","filePath":"zeugnisse/zp10.md"}'),s={name:"zeugnisse/zp10.md"};function u(i,e,l,o,d,h){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="zentrale-prufungen-und-klausuren-bearbeiten" tabindex="-1">Zentrale Prüfungen und Klausuren bearbeiten <a class="header-anchor" href="#zentrale-prufungen-und-klausuren-bearbeiten" aria-label="Permalink to &quot;Zentrale Prüfungen und Klausuren bearbeiten&quot;">​</a></h1><p>Bereiten Sie Prüfungsfächer und Notenarten vor, bevor Sie die Gruppenprozesse ausführen. Die Einzelansicht <a href="/schild3/schueler/zp10-zk-schueler.html">ZP10/ZK</a> erläutert den Bereich und grenzt die Zentrale Prüfung von der Zentralen Klausur ab.</p><p>Beachten Sie vor der Bearbeitung den <a href="/zeugnisse/zp10-rechtsstand.html">Rechtsstand zu Notenbildung und mündlichen Prüfungen</a>.</p><h2 id="die-prufung-vorbereiten" tabindex="-1">Die Prüfung vorbereiten <a class="header-anchor" href="#die-prufung-vorbereiten" aria-label="Permalink to &quot;Die Prüfung vorbereiten&quot;">​</a></h2><ol><li><a href="/schild3/unterricht-kataloge/faecher-und-teilleistungen-fuer-zp-10-und-zk-tutorial.html">Fächer und Teilleistungen für ZP10 und Zentrale Klausuren vorbereiten</a>.</li><li>Die passende Schülergruppe wählen und die <a href="/zeugnisse/sekundarstufen/zentrale-pruefung-jahrgang-10-gruppenprozesse-zp-10-zk.html">Gruppenprozesse</a> aufrufen.</li><li><a href="/schild3/suchen-gruppenprozesse/leistungsdaten-holen-gruppenprozesse-zentrale-klausuren.html">Leistungsdaten für die Zentrale Prüfung übernehmen</a> und bewusst über Notenart und Überschreiben entscheiden.</li></ol><h2 id="prufungsnoten-erfassen" tabindex="-1">Prüfungsnoten erfassen <a class="header-anchor" href="#prufungsnoten-erfassen" aria-label="Permalink to &quot;Prüfungsnoten erfassen&quot;">​</a></h2><ul><li>Vorhandene Werte: <a href="/zeugnisse/sekundarstufen/pruefungsnoten-aus-teilleistungen-holen-gruppenprozesse-zentrale-klausuren.html">ZP10-Prüfungsnoten aus Teilleistungen übernehmen</a>.</li><li>Direkte Eingabe: <a href="/zeugnisse/sekundarstufen/noten-eingeben-gruppenprozesse-zentrale-klausuren.html">ZP10-Prüfungsnoten gruppenweise eingeben</a>.</li><li>Vorbereitete Textdatei: <a href="/schild3/import-export-statistik/zp10-daten-verwaltung-import.html">Noten der Zentralen Prüfung 10 importieren</a>.</li></ul><h2 id="ergebnisse-prufen-und-ubertragen" tabindex="-1">Ergebnisse prüfen und übertragen <a class="header-anchor" href="#ergebnisse-prufen-und-ubertragen" aria-label="Permalink to &quot;Ergebnisse prüfen und übertragen&quot;">​</a></h2><ol><li>Nach vollständiger Noteneingabe <a href="/zeugnisse/sekundarstufen/muendliche-pruefungen-festlegen-gruppenprozesse-zentrale-klausuren.html">mündliche Prüfungen festlegen</a>.</li><li><a href="/zeugnisse/sekundarstufen/abschluss-berechnen-gruppenprozesse-zentrale-klausuren.html">ZP10-Abschlussnoten berechnen</a> und nicht eindeutig berechenbare Noten manuell festlegen.</li><li>Die geprüften <a href="/zeugnisse/sekundarstufen/abschlussnote-in-leistungsdaten-uebertragen-gruppenprozesse-zentrale-klausuren.html">Abschlussnoten in die Leistungsdaten übertragen</a>; dort vorhandene Noten werden überschrieben.</li></ol><p>Für die Ausgabe von Klausurdaten verwenden Sie <a href="/schild3/import-export-statistik/zk-daten-verwaltung-export.html">Daten zu Zentralen Klausuren exportieren</a>.</p>',10)])])}const f=n(s,[["render",u]]);export{g as __pageData,f as default};
